78	// regDiffMap 把一条结果的字段差异整理成 field -> {ledger, flow}。
79	func regDiffMap(r ReconResult) map[string][2]string {
80		out := make(map[string][2]string, len(r.Diffs))
81		for _, d := range r.Diffs {
82			out[d.Field] = [2]string{d.Ledger, d.Flow}
83		}
84		return out
85	}
