212			t.Fatalf("reconcile corrected: %v", err)
213		}
214		for i, r := range rep2.Results {
215			if r.Status != ReconMatched || len(r.Diffs) != 0 {
216				t.Fatalf("corrected result %d (%s)=%+v want matched", i, r.ID, r)
